import {GameControls} from './game-controls.js';
import { BridgeClient,localBridgeUrl } from './bridge-client.js';
const $=s=>document.querySelector(s);
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class BridgeUI {
 constructor(app){this.app=app;this.revision=null;this.points=[];this.client=new BridgeClient(()=>this.update());this.controls=new GameControls(this);document.addEventListener('click',e=>this.click(e),true);document.addEventListener('submit',e=>this.submit(e),true);this.client.start();this.afterRender();}
 get local(){return this.client.local;}
 async run(work){try{await work();}catch(e){this.app.toast(e.message||'No se pudo contactar con el puente.');}}
 open(){const c=this.client,s=c.state;if(!c.local){this.app.modal(`<p class="eyebrow">MISMA RED WI-FI</p><h2>Tu celular y tu PC, conectados.</h2><p>Inicia el puente en Windows y abre en el celular la dirección que muestra, por ejemplo <code>http://192.168.1.20:8787</code>. Introduce allí el código de seis dígitos del PC.</p><form id="bridge-address-form"><label class="field">Dirección del puente<input name="address" type="url" required placeholder="http://192.168.1.20:8787"></label><button class="btn primary" type="submit">Abrir puente local ↗</button></form><p>La versión local se sirve desde tu PC y permite leer el INI, importar FIT y recibir datos del adaptador del juego.</p>`);return;}
  this.app.modal(`<p class="eyebrow">CONEXIÓN POR WI-FI</p><h2>${c.token?'Tu centro de conexión.':'Empareja tu celular.'}</h2>${!c.token?'<p>Introduce el código que aparece en la ventana del puente en tu PC.</p><form id="bridge-pair-form"><label class="field">Código del PC<input name="pin" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required placeholder="000000"></label><button class="btn primary" type="submit">Conectar al PC</button></form>':`<div class="status-line"><span>Puente Windows</span><b>${s?'Enlazado':'Sin respuesta'}</b></div><div class="status-line"><span>Adaptador en GTA V</span><b>${s?.adapterConnected?'Enviando datos':'Esperando al juego'}</b></div><div class="status-line"><span>GTBikeV</span><b>${s?.modLoaded?'Detectado':'Sin detectar'}</b></div><div class="status-line"><span>Receptores ANT+ / BLE</span><b>${s?.trainerConnected?'Listos':'Sin datos'}</b></div><p>Potencia, pulso y cadencia aparecen cuando el mod recibe datos. Los valores no disponibles se muestran como —.</p><button class="btn ghost" data-action="bridge-unpair">Desconectar este celular</button>`}`);
 }
 afterRender(){if(!this.local)return;
  const timeNote=document.querySelector('.session-stats>div:nth-child(2)>p');if(timeNote)timeNote.textContent='Contador de GTBikeV';
  const heartCaption=document.querySelector('[data-live="heart"]')?.closest('.metric')?.querySelector('.metric-caption');if(heartCaption)heartCaption.textContent='Pulso recibido del mod';
  const panel=$('.workout-panel');if(panel){panel.querySelector('.eyebrow').textContent='CONTROL DE GTBIKEV';panel.querySelector('h2').textContent='Tu sesión en GTBikeV';panel.querySelector('.subtitle').textContent='El juego y tu bicicleta, en el mismo lugar.';panel.querySelector('.pill').textContent='EN EL PC';panel.querySelector('.workout-bars').hidden=true;panel.querySelector('.workout-bars').style.display='none';panel.querySelector('.workout-progress').hidden=true;panel.querySelector('.workout-time span:last-child').textContent='Tiempo del mod';}
  const actionBar=$('#settings-form .action-bar');if(actionBar&&!$('#bridge-config-actions')){const box=document.createElement('div');box.id='bridge-config-actions';box.className='action-bar';box.innerHTML='<button class="btn" type="button" data-action="bridge-load-config">Cargar INI del PC</button><button class="btn primary" type="button" data-action="bridge-save-config">Guardar INI en el PC</button><span class="tiny">Con copia de seguridad · Requiere reiniciar el mod</span>';actionBar.after(box);}
  if(location.hash==='#settings'){const note=$('#settings-form .notice');if(note)note.textContent='Carga el INI del PC antes de editarlo. Guardar en el PC crea una copia de seguridad; los ajustes se aplican al reiniciar el mod.';const label=$('.saved-label');if(label)label.textContent=this.revision?'INI del PC cargado · Listo para guardar':'Carga el INI del PC para sincronizar';}
  const importFit=$('[data-action="import-fit"]');if(importFit&&!$('[data-action="bridge-fits"]')){const button=document.createElement('button');button.type='button';button.className='btn';button.dataset.action='bridge-fits';button.textContent='FIT del PC';importFit.parentElement.append(button);}
  document.querySelectorAll('[data-action="workout"]').forEach(el=>el.disabled=true);
  document.querySelectorAll('.workout-panel .badge-demo').forEach(el=>el.textContent='PC');
  const workout=$('.workout-panel');if(workout&&!$('#bridge-workout-note')){const note=document.createElement('p');note.id='bridge-workout-note';note.className='tiny';note.style.lineHeight='1.6';note.textContent='Controles del mod: activación, ERG, potencia y solicitud de guardado. Detén la bicicleta antes de guardar.';workout.append(note);}
  const trainingNotice=$('.training-grid .notice');if(trainingNotice)trainingNotice.textContent='Los controles actúan sobre GTBikeV y esperan su respuesta. Los planes mostrados son ejemplos; sus intervalos no se envían automáticamente al juego.';
  this.controls.afterRender();this.update();
 }
 update(){if(!this.local)return;this.controls?.update();const c=this.client,s=c.state,m=s?.metrics??{};const mode=$('.demo-label');if(mode)mode.innerHTML='<span></span> WI-FI LOCAL';const connection=$('[data-action="connection"]');if(connection){connection.innerHTML=`<i style="background:${s?'#809a50':'#d49d65'}"></i><span>${s?'PC enlazado':c.token?'PC sin respuesta':'Emparejar PC'}</span><span>↗</span>`;}
  const status=$('.live-header .tiny');if(status)status.textContent=!c.token?'Introduce el código del PC':!s?'Puente sin respuesta':!s.adapterConnected?'PC enlazado · Esperando adaptador en GTA V':!s.trainerConnected?'GTBikeV detectado · Esperando sensores':'Datos reales de GTBikeV';
  if(!['','#dashboard','#training'].includes(location.hash))return;
  const f=(key,d=0)=>m[key]===null||m[key]===undefined?'—':Number(m[key]).toLocaleString('es-CO',{minimumFractionDigits:d,maximumFractionDigits:d});const values={power:f('powerW'),speed:f('speedKph',1),cadence:f('cadenceRpm'),heart:f('heartRateBpm'),distance:f('distanceKm',1),ascent:f('ascentM'),elapsed:m.elapsedSeconds==null?'—':this.app.time(m.elapsedSeconds),target:s?.targetPowerW==null?'—':String(s.targetPowerW)};
  for(const [key,value]of Object.entries(values))document.querySelectorAll(`[data-live="${key}"]`).forEach(el=>el.textContent=value);
  if($('#power-zone'))$('#power-zone').textContent=m.powerW==null?'Esperando datos':'Potencia del mod';
  const canErg=s?.commands?.includes('erg'),canTarget=s?.commands?.includes('target-power')&&s?.ergMode==='Engaged';document.querySelectorAll('[data-action="erg"]').forEach(el=>{el.disabled=!canErg;el.setAttribute('aria-checked',String(s?.ergMode==='Engaged'));});document.querySelectorAll('[data-action="target-up"],[data-action="target-down"]').forEach(el=>el.disabled=!canTarget);
  document.querySelectorAll('[data-action="session"]').forEach(el=>{el.disabled=!s?.commands?.includes('activate');el.textContent=s?.trainerConnected?'Desactivar mod':'Activar mod';});document.querySelectorAll('[data-action="finish"]').forEach(el=>{el.disabled=!s?.commands?.includes('save-activity')||m.speedKph==null||m.speedKph>=.18;el.setAttribute('aria-label','Solicitar finalización y guardado en GTBikeV');});
  if(s?.capturedAt!==this.lastCapture&&m.powerW!=null){this.lastCapture=s.capturedAt;const at=Date.parse(s.capturedAt);this.firstCapture??=at;this.points.push({t:(at-this.firstCapture)/1000,p:m.powerW});if(this.points.length>600)this.points.shift();}
  const liveChart=$('#live-chart');if(liveChart)liveChart.innerHTML=this.app.chart(s?.adapterConnected?this.points:[]);const chartCaption=liveChart?.closest('section')?.querySelector('.tiny');if(chartCaption)chartCaption.textContent=s?.adapterConnected?'Potencia recibida del mod':'Esperando datos reales';
 }
 click(e){const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='route'&&this.local){e.preventDefault();e.stopImmediatePropagation();this.controls.run(()=>this.controls.open('routes'));return;}if(a==='connection'){e.preventDefault();e.stopImmediatePropagation();this.open();return;}if(!this.local)return;
  if(['session','finish','workout','erg','target-up','target-down'].includes(a)){e.preventDefault();e.stopImmediatePropagation();if(a==='erg')this.run(()=>this.command('erg',{enabled:this.client.state?.ergMode!=='Engaged',targetPower:this.app.getTarget()}));else if(a==='target-up'||a==='target-down')this.run(()=>this.command('target-power',{watts:Math.max(50,Math.min(600,(this.client.state?.targetPowerW??180)+(a==='target-up'?5:-5)))}));else if(a==='session')this.run(()=>this.command('activate',{enabled:!this.client.state?.trainerConnected}));else if(a==='finish')this.run(()=>this.command('save-activity',{}));else this.app.toast('La selección de planes se hace por ahora en GTBikeV.');return;}
  if(!a.startsWith('bridge-'))return;e.preventDefault();e.stopImmediatePropagation();this.run(async()=>{
   if(a==='bridge-unpair'){await this.client.unpair();$('#modal').close();this.app.render();this.app.toast('Celular desconectado.');}
   if(a==='bridge-load-config'){const result=await this.client.request('/api/config');this.revision=result.revision;this.app.setConfig(result.text);this.app.render();this.app.toast('Configuración del PC cargada.');}
   if(a==='bridge-save-config'){if(!this.revision)throw Error('Carga primero el INI del PC.');if(!this.app.collectSettings())return;const result=await this.client.request('/api/config',{method:'PUT',body:{settings:this.app.getSettings(),revision:this.revision}});this.revision=result.revision;this.app.setConfig(result.text);this.app.render();this.app.toast('INI guardado con copia de seguridad. Reinicia el mod para aplicar los ajustes.');}
   if(a==='bridge-fits'){const result=await this.client.request('/api/activities');this.remoteFits=result.activities;this.app.modal(`<p class="eyebrow">ACTIVIDADES EN WINDOWS</p><h2>Tus FIT del PC.</h2><p>Selecciona una actividad para importarla al historial de este celular.</p>${result.activities.length?result.activities.map(f=>`<div class="setting-row"><span>${safe(f.name)}<small>${safe(new Date(f.modifiedAt).toLocaleDateString('es-CO'))} · ${Math.ceil(f.size/1024)} KB</small></span><button class="btn" data-action="bridge-import-fit" data-id="${safe(f.id)}">Importar</button></div>`).join(''):'<p>No se encontraron archivos FIT en la carpeta configurada del PC.</p>'}`);}
   if(a==='bridge-import-fit'){const item=this.remoteFits?.find(f=>f.id===b.dataset.id);if(!item)throw Error('Vuelve a cargar la lista de FIT.');const bytes=await this.client.request('/api/activities/'+item.id,{binary:true});const {parseActivity}=await import('./fit-import.js');this.app.addActivity({...parseActivity(bytes,item.name),id:'pc-'+item.id});$('#modal').close();location.hash='history';this.app.render();this.app.toast('FIT del PC importado al historial.');}
  });
 }
 submit(e){if(e.target.id==='bridge-address-form'){e.preventDefault();e.stopImmediatePropagation();const url=localBridgeUrl(new FormData(e.target).get('address'));if(!url){this.app.toast('Introduce una dirección IPv4 privada HTTP, por ejemplo http://192.168.1.20:8787');return;}location.assign(url);}
  if(e.target.id==='bridge-pair-form'){e.preventDefault();e.stopImmediatePropagation();const pin=new FormData(e.target).get('pin');this.run(async()=>{await this.client.pair(pin);$('#modal').close();this.app.render();this.app.toast('PC enlazado. Ya puedes cargar su INI y sus FIT.');});}
 }
 async command(action,params){const result=await this.client.request('/api/commands',{method:'POST',body:{action,...params}});await this.client.refresh();if(result.result?.gameUi&&this.client.state){this.client.state.gameUi=result.result.gameUi;this.update();}this.app.toast(action==='save-activity'?'Guardado solicitado al mod. Revisa el resumen en GTA V y la lista de FIT.':action==='activate'?'Acción de activación enviada al menú de GTBikeV.':result.message??'Orden confirmada por el mod.');return result;}
}
